// Signs a request to Convex: HMAC-SHA256 over "<timestamp>.<purpose>.<body>".
// The secret comes from the n8n environment (docker-compose / .env), never from this workflow.
const crypto = require('crypto');
function signFor(purpose, body) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret || secret.length < 32) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n environment');
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${purpose}.${body}`).digest('hex');
  return { timestamp, signature, body };
}

// GET has no body, so the signed string is "<timestamp>.overdue-list." (empty body).
return [{ json: signFor('overdue-list', '') }];

// One item per overdue loan. Convex already left out loans reminded today.
// No overdue loans → no items → the run ends here, successfully.
const { day, loans } = $input.first().json;
if (!Array.isArray(loans)) throw new Error('Convex answered without a loans list');
return loans.map((loan) => ({ json: { ...loan, day } }));

// A friendly reminder, using only the fields Convex sent for it.
const app = ($env.APP_URL || 'http://localhost:3000').replace(/\/$/, '');
const day = (d) => new Date(`${d}T00:00:00Z`).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
return $input.all().map(({ json: l }) => ({
  json: {
    loanId: l.loanId,
    day: l.day,
    to: l.email,
    subject: `Reminder: please return the ${l.toolName}`,
    text:
      `Hi ${l.firstName},\n\n` +
      `The ${l.toolName} you borrowed from ${l.ownerFirstName} was due back on ${day(l.dueDate)} ` +
      `(${l.daysOverdue} day${l.daysOverdue === 1 ? '' : 's'} ago).\n\n` +
      `Please arrange to return it, or message ${l.ownerFirstName} if you need a little longer.\n${app}/requests?tab=mine\n\n— LendLoop`,
  },
}));

// Signs a request to Convex: HMAC-SHA256 over "<timestamp>.<purpose>.<body>".
// The secret comes from the n8n environment (docker-compose / .env), never from this workflow.
const crypto = require('crypto');
function signFor(purpose, body) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret || secret.length < 32) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n environment');
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${purpose}.${body}`).digest('hex');
  return { timestamp, signature, body };
}

function errorText(json) {
  const e = json.error;
  if (!e) return json.message || 'Unknown error';
  return typeof e === 'string' ? e : (e.description || e.message || JSON.stringify(e)).slice(0, 500);
}

// Writes the outcome back to Convex. Convex treats a repeat of the same key as
// a no-op, so this node's retries can never create a second record.
return $input.all().map((item, i) => {
  const source = $('Compose reminder').itemMatching(i).json;
  const payload = { loanId: source.loanId, day: source.day, status: 'sent', executionId: String($execution.id) };
  return { json: signFor('reminder-result', JSON.stringify(payload)) };
});

